"""Infer current DC-side state from finite 24-row windows using our checkpoint."""
import argparse
from pathlib import Path
import numpy as np
import pandas as pd
import torch
from deep_model import BASE_FEATURES,TemporalEncoder,make_features


def predict(input_path,model_path,output_path):
    # Only checkpoints generated by this project; safe tensor-only loader.
    bundle=torch.load(model_path,map_location='cpu',weights_only=True)
    model=TemporalEncoder(width=bundle['width']);model.load_state_dict(bundle['state_dict']);model.eval()
    data=pd.read_csv(input_path)
    if set(BASE_FEATURES)-set(data):
        raise ValueError(f'Missing fields: {sorted(set(BASE_FEATURES)-set(data))}')
    raw=data[BASE_FEATURES].apply(pd.to_numeric,errors='coerce').to_numpy()
    features=make_features(raw)
    window=bundle['window']
    if len(data)<window:
        raise ValueError(f'At least {window} contiguous ordered rows required')
    # CSV caller supplies one device, ordered contiguous observations, in raw physical units.
    if 'inverter' in data and data.inverter.nunique(dropna=False)!=1:
        raise ValueError('CSV must contain a single device')
    mean=bundle['mean'].numpy();scale=bundle['scale'].numpy()
    indices=np.arange(len(data)-window+1)[:,None]+np.arange(window)
    tensor=np.transpose((features[indices]-mean)/scale,(0,2,1)).copy()
    predictions=[];scores=[]
    with torch.no_grad():
        for offset in range(0,len(tensor),256):
            probability=model(torch.from_numpy(tensor[offset:offset+256])).softmax(dim=1).numpy()
            predictions.extend(probability.argmax(axis=1).tolist());scores.extend(probability.max(axis=1).tolist())
    result=data.iloc[window-1:].copy()
    result['predicted_label']=predictions;result['uncalibrated_model_score']=scores
    result['status']='requires_domain_and_operator_validation'
    output_path.parent.mkdir(parents=True,exist_ok=True)
    result.to_csv(output_path,index=False)
    return len(result)


if __name__=='__main__':
    p=argparse.ArgumentParser()
    p.add_argument('input',type=Path);p.add_argument('--model',type=Path,required=True)
    p.add_argument('--output',type=Path,required=True)
    a=p.parse_args();print(predict(a.input,a.model,a.output))
